const trig=$('When called for one workflow').first().json;
const name=String(trig.name||'workflow');
const id=trig.id;
const sanitized=name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,80)||'workflow';
return[{json:{repo_owner:trig.repo_owner,repo_name:trig.repo_name,repo_path:trig.repo_path,repo_branch:trig.repo_branch||'main',fileName:`${sanitized}__${id}.json`,workflowName:name,workflowId:id}}];

const files=$input.all();
const workflows=$('Keep non-archived workflows').all();
const expected=new Set(workflows.map(i=>{
  const name=String(i.json.name||'workflow');
  const id=i.json.id;
  const sanitized=name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,80)||'workflow';
  return `${sanitized}__${id}.json`;
}));
const seen=new Set();
const orphans=[];
for(const item of files){
  const f=item.json;
  if(f.type&&f.type!=='file')continue;
  const name=f.name||'';
  const m=name.match(/__([A-Za-z0-9]+)\.json$/);
  if(!m)continue;
  if(expected.has(name))continue;
  const id=m[1];
  const filePath=f.path;
  if(!filePath||seen.has(filePath))continue;
  seen.add(filePath);
  orphans.push({json:{origin:'github',name,filePath,id,hasOrphans:true}});
}
if(orphans.length===0)return[{json:{hasOrphans:false}}];
return orphans;

const s=$getWorkflowStaticData('global');
s.backupCounts={processed:0,new:0,updated:0,unchanged:0,failed:0,deleted:0};
return $input.all().map(i=>({json:i.json}));

const gv=$('Lookup global variables').first().json;
const raw=String(gv.backup_gh_path??'').replace(/^\/+/, '');
const repo_path=!raw||raw.endsWith('/')?raw:`${raw}/`;
return $input.all().map(i=>({json:{...i.json,repo_owner:gv.backup_gh_owner,repo_name:gv.backup_gh_repo,repo_path,repo_branch:'main'}}));

const s=$getWorkflowStaticData('global');
if(!s.backupCounts)s.backupCounts={processed:0,new:0,updated:0,unchanged:0,failed:0,deleted:0};
const out=[];
for(const item of $input.all()){
  s.backupCounts.processed++;
  const st=item.json.github_status;
  if(st==='new')s.backupCounts.new++;
  else if(st==='different')s.backupCounts.updated++;
  else s.backupCounts.unchanged++;
  out.push({json:{github_status:st||'same',tallied:true}});
}
return out;

const s=$getWorkflowStaticData('global');
if(!s.backupCounts)s.backupCounts={processed:0,new:0,updated:0,unchanged:0,failed:0,deleted:0};
s.backupCounts.failed++;
s.backupCounts.processed++;
return [{json:{tallied:true,github_status:'failed'}}];

const s=$getWorkflowStaticData('global');
if(!s.backupCounts)s.backupCounts={processed:0,new:0,updated:0,unchanged:0,failed:0,deleted:0};
const items=$input.all();
s.backupCounts.deleted+=items.length;
return items.map(i=>({json:{...i.json,tallied:true}}));

const s=$getWorkflowStaticData('global');
const c=s.backupCounts||{processed:0,new:0,updated:0,unchanged:0,failed:0,deleted:0};
return [{json:{...c}}];

const gv=$input.first().json;
const isSet=(v)=>{const s=String(v??'').trim();if(!s)return false;if(/^YOUR_/i.test(s))return false;return true;};
const backup_gh_ready=isSet(gv.backup_gh_owner)&&isSet(gv.backup_gh_repo)&&isSet(gv.backup_gh_path);
return[{json:{...gv,backup_gh_ready}}];

